WITH late AS (SELECT emp_id,SUM(CASE WHEN late_minutes>0 THEN 1 ELSE 0 END) late_arrivals,SUM(late_minutes) late_minutes FROM warehouse_attendance_daily GROUP BY emp_id), ref AS (SELECT e.emp_id,e.full_name,CASE WHEN e.separation_date<>'' AND e.separation_date<'2026-09-30' THEN e.separation_date ELSE '2026-09-30' END asof_date FROM staging_employees e) SELECT l.emp_id,l.late_arrivals,l.late_minutes,r.full_name,d.dept_id,d.dept_name FROM late l JOIN ref r USING(emp_id) LEFT JOIN warehouse_employees h ON h.emp_id=l.emp_id AND h.valid_from<=r.asof_date AND (h.valid_to='' OR h.valid_to>=r.asof_date) LEFT JOIN warehouse_departments d ON d.dept_id=h.dept_id WHERE l.late_arrivals>0 ORDER BY l.late_arrivals DESC,l.late_minutes DESC LIMIT 10;
